window.kbPageData["views/entry/k-43348f1370d6f13c"] = {"key":"entry/k-43348f1370d6f13c","state":{"route":"entry/k-43348f1370d6f13c"},"node":{"id":"k-43348f1370d6f13c","mode":"k","title":"省级消费者协会的消费民事公益诉讼资格","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["省级消费者保护组织可依法提起消费民事公益诉讼"],"qs":["江苏 2023 B类 行测#15"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"依《消费者权益保护法》第四十七条，对侵害众多消费者合法权益的行为，中国消费者协会和在省、自治区、直辖市设立的消费者协会可以向人民法院提起消费民事公益诉讼。","review":{"definition":"依《消费者权益保护法》第四十七条，对侵害众多消费者合法权益的行为，中国消费者协会和在省、自治区、直辖市设立的消费者协会可以向人民法院提起消费民事公益诉讼。","explanation":"题中的开机广告设置随电视销售影响众多消费者，周某的个体诉讼与省级消费者组织代表公共消费利益提起的诉讼可以分别成立。类似案件中，江苏省消费者权益保护委员会依法承接原省消费者协会的公益性职责，已作为原告提起同类诉讼。D项属于正确说法，本题要求选不正确的一项。","references":[{"source":"web-92b6031946f2d189","location":"第四十七条","quote":"对侵害众多消费者合法权益的行为"},{"source":"web-2e8cf6526505edbd","location":"智能电视开机广告案，基本案情","quote":"代替原“江苏省消费者协会”履行"}],"evidence":"J省消费者保护委员会也准备提起消费民事公益诉讼","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#15":{"paper":"江苏 2023 B类 行测","n":15,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",6],"card":"66101090aa309c4eebdfef44","links":[{"id":"k-43348f1370d6f13c","role":"解题依据","why":"该规则决定省级消费者保护委员会能否作为本案的公益诉讼主体。"}]}},"terms":{},"references":{"web-92b6031946f2d189":{"name":"《中华人民共和国消费者权益保护法》","url":"https://www.samr.gov.cn/zfjcj/tzgg/art/2023/art_615af9ed6bcd4974bf853dd2e02bc663.html"},"web-2e8cf6526505edbd":{"name":"最高人民法院《人民法院高质量服务保障长三角一体化发展典型案例》","url":"https://www.court.gov.cn/zixun/xiangqing/400542.html"}},"topics":[],"units":{"k-43348f1370d6f13c":[["江苏 2023 B类 行测#15"]]}};
